from pathlib import Path
p=Path('ClockTimer.js')
s=p.read_text()
old='''            const openEnded =\n                !explicitStart &&\n                !hasEnd &&\n                !hasLength;'''
new='''            const openEnded =\n                !hasEnd &&\n                !hasLength;'''
assert old in s
s=s.replace(old,new,1)
old2='''            if (\n                explicitStart &&\n                !hasEnd &&\n                !hasLength\n            ) {\n                return;\n            }\n\n'''
assert old2 in s
s=s.replace(old2,'',1)
marker='''        #tick() {\n'''
assert marker in s
helper='''        #processElapsedOverwriteRanges(\n            now\n        ) {\n            const ranges =\n                this.#getManagedTimeRanges()\n                    .filter(\n                        range =>\n                            range.timeRangeExiting !== true &&\n                            range.hasAttribute(\n                                "overwrite"\n                            )\n                    );\n\n            for (const range of ranges) {\n                const end =\n                    Number(\n                        range.clockTimerEnd\n                    );\n\n                if (\n                    !Number.isFinite(end) ||\n                    now < end\n                ) {\n                    continue;\n                }\n\n                const overwriteType =\n                    range.getAttribute(\n                        "overwrite"\n                    )?.trim();\n\n                if (!overwriteType) {\n                    continue;\n                }\n\n                const nextRange =\n                    this.#getManagedTimeRanges()\n                        .filter(\n                            candidate =>\n                                candidate !== range &&\n                                candidate.timeRangeExiting !== true &&\n                                candidate.getAttribute(\n                                    "type"\n                                ) !== "elapsed"\n                        )\n                        .map(\n                            candidate => ({\n                                range: candidate,\n                                start: Number(\n                                    candidate.clockTimerStart\n                                ),\n                                end: Number(\n                                    candidate.clockTimerEnd\n                                )\n                            })\n                        )\n                        .filter(\n                            item =>\n                                Number.isFinite(item.start) &&\n                                Number.isFinite(item.end) &&\n                                item.end > item.start &&\n                                item.start >= end\n                        )\n                        .sort(\n                            (a, b) =>\n                                a.start - b.start ||\n                                a.end - b.end\n                        )[0];\n\n                range.removeAttribute(\n                    "overwrite"\n                );\n\n                if (nextRange) {\n                    this.overwrite({\n                        type: overwriteType,\n                        startTime:\n                            this.#formatTimelineTime(\n                                nextRange.start\n                            ),\n                        endTime:\n                            this.#formatTimelineTime(\n                                nextRange.end\n                            )\n                    });\n\n                    continue;\n                }\n\n                this.overwrite({\n                    type: overwriteType,\n                    startTime:\n                        this.#formatTimelineTime(\n                            end\n                        )\n                });\n            }\n        }\n\n'''
s=s.replace(marker,helper+marker,1)
old3='''            this.#freezeIndicatorForRingHandoff(\n                now\n            );\n\n            this.#ensureRing('''
new3='''            this.#processElapsedOverwriteRanges(\n                now\n            );\n\n            this.#freezeIndicatorForRingHandoff(\n                now\n            );\n\n            this.#ensureRing('''
assert old3 in s
s=s.replace(old3,new3,1)
p.write_text(s)
